#include <iostream>

int divisorSum(int n)
{
    int total{};

    for (int d = 1; d < n; ++d)
    {
        if (n % d == 0) total += d;
    }

    return total;
}

bool isPerfect(int n)
{
    return n == divisorSum(n);
}

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    bool found{};

    for (int k = 1; k <= n; ++k)
    {
        if (isPerfect(k))
        {
            std::cout << k << "\n";
            found = true;
        }
    }

    if (!found) std::cout << "none\n";

    return 0;
}
